import {engine,clone,text,list,unique,record,object,mdField} from '../workshop-kit/state.js?v=0.7.0';
export const LEVELS={step:{name:'Change a step',verb:'Do the work differently',prompt:'What could you simplify, remove, or replace inside this step?'},handoff:{name:'Repair a handoff',verb:'Change who passes what',prompt:'What agreement or transfer between people needs to change?'},delay:{name:'Change the timing',verb:'Move a wait or feedback loop',prompt:'What happens too early, too late, or after an avoidable wait?'},information:{name:'Change the information',verb:'Make a signal usable',prompt:'Who needs to see what before making this decision?'},rule:{name:'Change the rule',verb:'Alter what is permitted or rewarded',prompt:'What threshold, permission, or incentive produces this behaviour?'},goal:{name:'Change the goal',verb:'Question what “better” means',prompt:'What is being optimised, and what outcome should matter instead?'}};
const OPTION_FIELDS=['title','change','why','tradeoff','test','evidence'];
export const newOption=(id,anchor,level)=>({id,anchor,level,...Object.fromEntries(OPTION_FIELDS.map(key=>[key,''])),review:false});
export function create(id='first',example='example'){
  if(!['example','battery','blank'].includes(example))throw new Error('Unknown example.');
  const battery=example==='battery',blank=example==='blank';
  const steps=(blank?[['','']]:battery?[['A dispatch opportunity appears','The expected value is compared with the current operating plan.'],['Operating limits are checked','Availability and service commitments constrain the choice.'],['A decision waits for clarification','The owner of an exception is not always clear.'],['The opportunity passes','A slow decision can consume a short operating window.']]:[['A team requests a review','A question enters the queue, sometimes before the work is ready.'],['Specialists ask for missing context','Clarification happens after a review slot has been reserved.'],['The item waits for the weekly meeting','Even reversible choices use the same approval route.'],['The decision arrives too late','Work is delayed or proceeds without the useful feedback.']]).map(([name,mechanism],i)=>({id:`${id}-s${i+1}`,name,mechanism}));
  const options=[];
  if(!blank){const rows=battery?[['information',1,'Expose the binding limit','Show the binding limit beside the proposed dispatch.','The decision can address the actual constraint instead of revisiting every assumption.'],['handoff',2,'Name the exception owner','Give each exception a named decision owner and response window.','Ownership makes a clarification actionable before the opportunity expires.'],['goal',3,'Value timely decisions','Review decision latency alongside captured value.','This may reveal missed value caused by slow coordination.']]:[['step',0,'Make a question ready first','Require one decision question and the context needed to answer it.','Specialists can use the review slot to decide, rather than discover what is missing.'],['information',1,'Signal readiness before booking','Show whether the needed evidence is available before reserving a review slot.','Incomplete requests can be clarified before they consume scarce review time.'],['rule',2,'Use a lighter route for reversible choices','Allow a named owner to decide reversible, low-impact choices after a short objection window.','A proportionate approval rule removes unnecessary waiting without removing accountability.']];for(const [level,index,title,change,why]of rows)options.push({...newOption(`${id}-o${options.length+1}`,steps[index].id,level),title,change,why});}
  return{id,problem:blank?'':battery?'Why do useful battery dispatch decisions arrive too late?':'Why do product decisions keep arriving after they would have helped?',steps,options,selectedId:options[1]?.id||null,chosenId:null};
}
export function reduce(value,action){const work=clone(value),option=work.options.find(item=>item.id===action.id),step=work.steps.find(item=>item.id===action.id);switch(action.type){
  case'problem':work.problem=text(action.value);break;
  case'step':if(!step||!['name','mechanism'].includes(action.field))throw new Error('Step not found.');step[action.field]=text(action.value);work.options.filter(item=>item.anchor===step.id).forEach(item=>item.review=true);break;
  case'add-step':if(work.steps.length>=7||work.steps.some(item=>item.id===action.id))throw new Error('Keep at most seven unique steps.');work.steps.push({id:text(action.id,true),name:'',mechanism:''});break;
  case'remove-step':if(!step)throw new Error('Step not found.');if(work.steps.length===1)throw new Error('Keep at least one mechanism step.');if(work.options.some(item=>item.anchor===step.id))throw new Error('Move this step’s interventions to another step before removing it.');work.steps=work.steps.filter(item=>item.id!==step.id);break;
  case'reorder-step':{const index=work.steps.findIndex(item=>item.id===action.id),next=index+action.direction;if(index<0||![-1,1].includes(action.direction)||next<0||next>=work.steps.length)throw new Error('This step cannot move further.');[work.steps[index],work.steps[next]]=[work.steps[next],work.steps[index]];break;}
  case'add-option':if(work.options.length>=24||work.options.some(item=>item.id===action.id)||!work.steps.some(step=>step.id===action.anchor)||!Object.hasOwn(LEVELS,action.level))throw new Error('Choose a valid step and level; keep at most 24 interventions.');work.options.push(newOption(text(action.id,true),action.anchor,action.level));work.selectedId=action.id;break;
  case'option':if(!option||!OPTION_FIELDS.includes(action.field))throw new Error('Intervention field not found.');option[action.field]=text(action.value);break;
  case'move-option':action={...action,level:action.level??action.value};if(!option||!Object.hasOwn(LEVELS,action.level)||!work.steps.some(step=>step.id===action.anchor))throw new Error('Choose a valid step and level.');if(option.level!==action.level||option.anchor!==action.anchor)option.review=true;option.level=action.level;option.anchor=action.anchor;work.selectedId=option.id;break;
  case'reviewed':if(!option)throw new Error('Intervention not found.');option.review=false;break;
  case'select':if(!option)throw new Error('Intervention not found.');work.selectedId=option.id;break;
  case'choose':if(!option)throw new Error('Intervention not found.');work.chosenId=option.id;work.selectedId=option.id;break;
  case'remove-option':if(!option)throw new Error('Intervention not found.');work.options=work.options.filter(item=>item.id!==option.id);if(work.selectedId===option.id)work.selectedId=work.options[0]?.id||null;if(work.chosenId===option.id)work.chosenId=null;break;
  default:throw new Error('Unknown action.');}return work;}
export function validate(value){if(!object(value))throw new Error('Invalid intervention workspace.');const steps=unique(list(value.steps,7,'steps').map(step=>({id:text(step.id,true),...record(step,['name','mechanism'])})));if(!steps.length)throw new Error('A mechanism needs a step.');const options=unique(list(value.options,24,'interventions').map(item=>{if(!object(item)||!Object.hasOwn(LEVELS,item.level)||!steps.some(step=>step.id===item.anchor)||typeof item.review!=='boolean')throw new Error('An intervention has a missing mechanism.');return{id:text(item.id,true),anchor:item.anchor,level:item.level,review:item.review,...record(item,OPTION_FIELDS)};}));for(const key of['selectedId','chosenId'])if(value[key]!==null&&!options.some(item=>item.id===value[key]))throw new Error('Intervention selection is inconsistent.');return{id:text(value.id,true),problem:text(value.problem),steps,options,selectedId:value.selectedId,chosenId:value.chosenId};}
export const model=engine({kind:'thinking-lab-interventions',create,validate,reduce});
export function markdown(work){const parts=['# Intervention ladder','',work.problem,'','## Hypothesised mechanism',''];work.steps.forEach((step,index)=>parts.push(`### ${index+1}. ${step.name||'Unnamed step'}`,'',step.mechanism||'_Not written._',''));for(const item of work.options){parts.push(`## ${item.title||'Untitled intervention'}${work.chosenId===item.id?' · chosen':''}`,'',`Level: ${LEVELS[item.level].name}`,'',`Affects: ${work.steps.find(step=>step.id===item.anchor).name||'Unnamed step'}`,'',item.review?'Context changed; causal claim needs review.\n':'',mdField('Change',item.change),mdField('Why this changes the outcome',item.why),mdField('Trade-off or permission',item.tradeoff),mdField('Smallest test',item.test),mdField('What would change my mind',item.evidence));}return parts.join('\n');}
